package android.content;
import java.util.*;import android.net.Uri;
public class Intent{public static final String ACTION_SEND_MULTIPLE="android.intent.action.SEND_MULTIPLE",EXTRA_STREAM="android.intent.extra.STREAM";public static final int FLAG_GRANT_READ_URI_PERMISSION=1;public final String action;public String mime;public int flags;public ArrayList<Uri> streams;public ClipData clip;public Intent(String action){this.action=action;}public Intent setType(String mime){this.mime=mime;return this;}public Intent putParcelableArrayListExtra(String key,ArrayList<Uri> streams){this.streams=streams;return this;}public Intent addFlags(int flags){this.flags|=flags;return this;}public Intent setClipData(ClipData clip){this.clip=clip;return this;}public static Intent createChooser(Intent intent,String title){return intent;}}
